#!/bin/bash
# The test doubles of the MWBase interfaces (apps/openmw_tests/mwmechanics/fakes/*.inc) are generated by
# tools/mwbase_fakes/gen.py from the interface headers and committed (task 0085 move 2). When an interface gains,
# loses or changes a pure virtual function and nobody regenerates its double, the tests stop compiling for a reason that
# is hard to see, or worse a double silently keeps a stale signature. This regenerates every double and fails when the
# output differs from the committed file (line endings are ignored: a Windows checkout has CRLF).
# Run from the repository root; a path to another root may be given as the first argument (the self-test uses a copy).
set -u
root="${1:-.}"
cd "$root" || exit 2

python=""
for candidate in python3 python; do
    if command -v "$candidate" >/dev/null 2>&1 && "$candidate" -c 'import sys; sys.exit(0 if sys.version_info[0] == 3 else 1)' 2>/dev/null; then
        python="$candidate"
        break
    fi
done
if [ -z "$python" ]; then
    echo "check_mwbase_fakes: Python 3 not found"
    exit 2
fi

# header (under apps/openmw/mwbase), class, generated base class, committed output
doubles="
world.hpp World GeneratedWorldBase world.inc
windowmanager.hpp WindowManager GeneratedWindowManagerBase windowmanager.inc
mechanicsmanager.hpp MechanicsManager GeneratedMechanicsManagerBase mechanicsmanager.inc
luamanager.hpp LuaManager GeneratedLuaManagerBase luamanager.inc
"
status=0
while read -r header class base out; do
    [ -n "$header" ] || continue
    committed="apps/openmw_tests/mwmechanics/fakes/$out"
    if [ ! -f "$committed" ]; then
        echo "check_mwbase_fakes: $committed is missing"
        status=1
        continue
    fi
    generated="$("$python" tools/mwbase_fakes/gen.py "apps/openmw/mwbase/$header" "$class" "$base" | tr -d '\r')" || {
        echo "check_mwbase_fakes: gen.py failed on apps/openmw/mwbase/$header"
        status=1
        continue
    }
    if ! diff <(printf '%s\n' "$generated") <(tr -d '\r' < "$committed") >/dev/null; then
        echo "check_mwbase_fakes: $committed is out of date with apps/openmw/mwbase/$header; regenerate it:"
        echo "    $python tools/mwbase_fakes/gen.py apps/openmw/mwbase/$header $class $base > $committed"
        diff <(printf '%s\n' "$generated") <(tr -d '\r' < "$committed") | head -20
        status=1
    fi
done <<<"$doubles"
[ "$status" = 0 ] && echo "check_mwbase_fakes: the four doubles match their interfaces"
exit "$status"
